"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant2 from "./components/agent-chat-input/variants/03-studio-composer";
const variants = {
  "studio-composer": Variant2,
};
export interface ArtemisAgentChatInputProps {
  className?: string;
  variant?: "studio-composer";
}
export function ArtemisAgentChatInput({
  className,
  variant = "studio-composer",
}: ArtemisAgentChatInputProps) {
  const View = variants[variant];
  return (
    <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}>
      <View />
    </ArtemisScope>
  );
}

