"use client";
// @zeus-internal
import { StudioButton } from "./03-studio-composer/button";
import { useState, useRef, useEffect, useId } from "react";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { Square } from "lucide-react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_LAYOUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { ArtemisMorphicTooltip, ArtemisMorphicTooltipProvider } from "./03-studio-composer/tooltip";
import { AttachmentStrip, type StudioAttachment } from "./03-studio-composer/attachments";
import { StudioActionsMenu, StudioAgentMenu, StudioModelMenu } from "./03-studio-composer/menus";
export default function AgentChatInputStudioComposer() {
    const [draft, setDraft] = useState("");
    const [attachments, setAttachments] = useState<StudioAttachment[]>([]);
    const nextAttachment = useRef(0);
    const urls = useRef<string[]>([]);
    useEffect(() => () => urls.current.forEach(url => URL.revokeObjectURL(url)), []);
    const addFiles = (files: File[]) => setAttachments(current => [...current, ...files.map(file => ({ id: nextAttachment.current++, file, url: "" }))]);
    useEffect(() => {
        if (!attachments.some(attachment => !attachment.url))
            return;
        setAttachments(current => current.map(attachment => {
            if (attachment.url)
                return attachment;
            const url = URL.createObjectURL(attachment.file);
            urls.current.push(url);
            return { ...attachment, url };
        }));
    }, [attachments]);
    const [focused, setFocused] = useState(false);
    const [queued, setQueued] = useState(true);
    const [status, setStatus] = useState<"ready" | "submitted" | "streaming">("ready");
    const [agent, setAgent] = useState("Coding agent");
    const [model, setModel] = useState("Nova 5.5");
    const [reasoning, setReasoning] = useState("High");
    const [speed, setSpeed] = useState("Auto");
    const [plan, setPlan] = useState(false);
    const [goal, setGoal] = useState(false);
    const editorRef = useRef<HTMLDivElement>(null);
    const fileRef = useRef<HTMLInputElement>(null);
    const editorId = useId();
    const fileId = useId();
    const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
    const busy = status !== "ready";
    const reduce = useReducedMotion();
    const press = { whileHover: reduce ? undefined : { scale: 1.01 }, whileTap: reduce ? undefined : { scale: 0.96 }, transition: ARTEMIS_SPRING_PRESS };
    const iconPress = { ...press, whileTap: reduce ? undefined : { scale: 0.92 } };
    const queueSpring = ARTEMIS_SPRING_PRESS;
    const queueHover = reduce ? undefined : { scale: 1.01, transition: queueSpring };
    const queueRest = { scale: 1, transition: queueSpring };
    useEffect(() => () => timers.current.forEach(clearTimeout), []);
    const send = () => { if (busy || (!draft.trim() && !attachments.length))
        return; setDraft(""); setAttachments([]); if (editorRef.current)
        editorRef.current.textContent = ""; setStatus("submitted"); timers.current.push(setTimeout(() => setStatus("streaming"), 500), setTimeout(() => setStatus("ready"), 1800)); };
    const stop = () => { setStatus("ready"); };
    return (<ArtemisMorphicTooltipProvider delay={180}>
      <div className="art:flex art:w-full art:max-w-3xl art:flex-col art:justify-end">
        <div className="art:relative art:w-full art:max-w-full art:text-base art:[&_button]:text-sm" data-status={status}>
          <AnimatePresence initial={false}>{queued && <motion.div layout initial={false} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 6, scale: 0.99 }} transition={ARTEMIS_SPRING_LAYOUT} className="art:relative art:z-0 art:mx-auto art:@min-[768px]/artemis:w-[94%] art:w-[88%] art:overflow-hidden art:rounded-t-2xl art:border art:border-border/70 art:bg-background/70 art:px-2 art:py-1 art:backdrop-blur-xl">
            <div className="art:group art:flex art:min-h-8 art:items-center art:gap-2 art:rounded-xl art:px-2 art:text-muted-foreground art:text-sm" style={{ opacity: "1", transform: "none" }}>
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-corner-down-right art:size-4 art:shrink-0 art:opacity-70" aria-hidden="true">
                <path d="m15 10 5 5-5 5"/>
                <path d="M4 4v7a4 4 0 0 0 4 4h12"/>
              </svg>
              <span className="art:min-w-0 art:flex-1 art:truncate art:font-medium">
                {"research"}
              </span>
              <div className="art:ml-auto art:flex art:items-center art:gap-1 art:opacity-75 art:transition-opacity art:group-hover:opacity-100 art:group-focus-within:opacity-100">
                <ArtemisMorphicTooltip content="Steer queued message"><StudioButton {...press} animate={queueRest} whileHover={queueHover} whileTap={reduce ? undefined : { scale: 0.96, transition: ARTEMIS_SPRING_PRESS }} type="button" className="art:justify-center art:select-none art:text-sm art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:p-0 art:font-normal art:inline-flex art:h-7 art:items-center art:gap-1 art:px-1.5 art:text-muted-foreground art:transition-colors art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:disabled:pointer-events-none art:disabled:opacity-50 art:rounded-full" aria-label="Steer research" tabIndex={0}>
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-corner-down-right art:size-3.5" aria-hidden="true">
                      <path d="m15 10 5 5-5 5"/>
                      <path d="M4 4v7a4 4 0 0 0 4 4h12"/>
                    </svg>
                    <span className="art:hidden art:@min-[640px]/artemis:inline">
                      {"Steer"}
                    </span>
                  </StudioButton></ArtemisMorphicTooltip>
                <ArtemisMorphicTooltip content="Remove queued message">
                  <StudioButton {...iconPress} animate={queueRest} whileHover={queueHover} whileTap={reduce ? undefined : { scale: 0.92, transition: ARTEMIS_SPRING_PRESS }} type="button" className="art:items-center art:justify-center art:select-none art:gap-2 art:text-sm art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:p-0 art:font-normal art:grid art:size-7 art:place-items-center art:text-muted-foreground art:transition-colors art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:disabled:pointer-events-none art:disabled:opacity-50 art:rounded-full" onClick={() => setQueued(false)} aria-label="Remove research" tabIndex={0}>
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-trash2 art:lucide-trash-2 art:size-3.5" aria-hidden="true">
                      <path d="M10 11v6"/>
                      <path d="M14 11v6"/>
                      <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6"/>
                      <path d="M3 6h18"/>
                      <path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/>
                    </svg>
                  </StudioButton>
                </ArtemisMorphicTooltip>
                <ArtemisMorphicTooltip content="Edit queued message"><StudioButton {...iconPress} type="button" className="art:items-center art:justify-center art:select-none art:gap-2 art:text-sm art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:p-0 art:font-normal art:grid art:size-7 art:place-items-center art:text-muted-foreground art:transition-colors art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:disabled:pointer-events-none art:disabled:opacity-50 art:rounded-full" aria-label="Edit research" tabIndex={0}>
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-pen-line art:size-3.5" aria-hidden="true">
                      <path d="M13 21h8"/>
                      <path d="M21.174 6.812a1 1 0 0 0-3.986-3.987L3.842 16.174a2 2 0 0 0-.5.83l-1.321 4.352a.5.5 0 0 0 .623.622l4.353-1.32a2 2 0 0 0 .83-.497z"/>
                    </svg>
                  </StudioButton></ArtemisMorphicTooltip>
              </div>
            </div>
          </motion.div>}</AnimatePresence>
          <motion.div className={"art:relative art:rounded-3xl " + (attachments.length ? "art:overflow-visible" : "art:overflow-hidden")} data-textarea-focused={focused} initial={false} animate={{ padding: attachments.length ? 4 : 0 }} transition={{ duration: .3, ease: ARTEMIS_EASE_OUT }}>
            <motion.div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0 art:rounded-3xl art:bg-background/60" initial={false} animate={{ opacity: attachments.length ? 1 : 0 }} transition={{ duration: .3, ease: ARTEMIS_EASE_OUT }}/>
            <AttachmentStrip attachments={attachments} onRemove={id => setAttachments(current => current.filter(file => file.id !== id))}/>
            <div className="art:relative">
              <div className={"art:relative art:rounded-3xl art:border art:border-border art:bg-background art:data-[textarea-focused=true]:border-border-strong " + (attachments.length ? "art:overflow-visible" : "art:overflow-hidden")} data-textarea-focused={focused}>
                <div id={editorId} role="textbox" aria-multiline="true" aria-label="Agent prompt" aria-disabled="false" ref={editorRef} contentEditable suppressContentEditableWarning onFocus={() => setFocused(true)} onBlur={() => setFocused(false)} onInput={event => setDraft(event.currentTarget.innerText)} onPaste={event => { const text = event.clipboardData.getData("text/plain"); if (!text)
        return; event.preventDefault(); document.execCommand("insertText", false, text); setDraft(event.currentTarget.innerText); }} onKeyDown={event => { if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) {
        event.preventDefault();
        send();
    } }} data-placeholder="Ask for follow-up changes" data-empty={!draft} style={{ minHeight: "3.5rem", maxHeight: "12.25rem" }} className="art:w-full art:overflow-y-auto art:whitespace-pre-wrap art:break-words art:px-4 art:pt-4 art:pb-3 art:text-base art:outline-none art:@min-[640px]/artemis:px-5 art:@min-[640px]/artemis:pt-5 art:@min-[768px]/artemis:text-lg art:data-[empty=true]:before:pointer-events-none art:data-[empty=true]:before:text-muted-foreground/70 art:data-[empty=true]:before:content-[attr(data-placeholder)] art:placeholder:text-muted-foreground/70 art:min-h-16 art:!text-base art:leading-6"/>
                <div className="art:flex art:items-center art:justify-between art:gap-2 art:px-2.5 art:pb-2 art:@min-[640px]/artemis:gap-3 art:@min-[640px]/artemis:px-4 art:[&_button]:text-base">
                  <div className="art:flex art:min-w-0 art:items-center art:gap-1.5">
                    <StudioActionsMenu className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:text-foreground art:focus-visible:outline-none art:hover:bg-muted art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring/40 art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:data-[artemis-pointer-focus]:focus-visible:shadow-none art:data-[artemis-pointer-focus]:focus-visible:ring-0 art:data-[artemis-pointer-focus]:focus-visible:ring-offset-0 art:size-9 art:h-9 art:rounded-full" disabled={busy} plan={plan} goal={goal} onPlan={() => setPlan(v => !v)} onGoal={() => setGoal(v => !v)} onAttach={() => fileRef.current?.click()}/>
                    <StudioAgentMenu className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:text-foreground art:text-sm art:focus-visible:outline-none art:hover:bg-muted art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring/40 art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:data-[artemis-pointer-focus]:focus-visible:shadow-none art:data-[artemis-pointer-focus]:focus-visible:ring-0 art:data-[artemis-pointer-focus]:focus-visible:ring-offset-0 art:group art:max-w-[7.5rem] art:gap-1.5 art:px-2 art:@min-[640px]/artemis:max-w-[11rem] art:@min-[640px]/artemis:px-2.5 art:h-9 art:rounded-full" disabled={busy} value={agent} onChange={setAgent}/>
                  </div>
                  <div className="art:flex art:shrink-0 art:items-center art:gap-1 art:@min-[640px]/artemis:gap-1.5">
                    <StudioModelMenu className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:text-foreground art:text-sm art:focus-visible:outline-none art:hover:bg-muted art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring/40 art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:data-[artemis-pointer-focus]:focus-visible:shadow-none art:data-[artemis-pointer-focus]:focus-visible:ring-0 art:data-[artemis-pointer-focus]:focus-visible:ring-offset-0 art:group art:gap-1.5 art:px-2 art:@min-[640px]/artemis:px-3 art:h-9 art:rounded-full" disabled={busy} model={model} reasoning={reasoning} speed={speed} onModel={setModel} onReasoning={setReasoning} onSpeed={setSpeed}/>
                    <div className="art:hidden art:@min-[640px]/artemis:block">
                      <ArtemisMorphicTooltip content="Voice input">
                        <StudioButton {...press} type="button" className="art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:p-0 art:font-normal art:inline-flex art:h-9 art:min-w-9 art:items-center art:justify-center art:text-muted-foreground art:text-sm art:transition-colors art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:data-[active=true]:bg-primary/5 art:data-[active=true]:text-foreground art:rounded-full" disabled aria-label="Voice input" aria-pressed="false" data-active="false" tabIndex={0}>
                          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-mic art:size-4" aria-hidden="true">
                            <path d="M12 19v3"/>
                            <path d="M19 10v2a7 7 0 0 1-14 0v-2"/>
                            <rect x="9" y="2" width="6" height="13" rx="3"/>
                          </svg>
                        </StudioButton>
                      </ArtemisMorphicTooltip>
                    </div>
                    <ArtemisMorphicTooltip content={busy ? "Stop response" : "Send message"}>
                      <StudioButton {...press} type="button" className="art:items-center art:justify-center art:select-none art:disabled:pointer-events-none art:gap-2 art:text-sm art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:p-0 art:font-normal art:hover:text-inherit art:grid art:size-8 art:place-items-center art:text-primary-foreground art:transition-colors art:bg-primary art:hover:bg-primary/90 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:disabled:cursor-not-allowed art:disabled:opacity-45 art:rounded-full" disabled={!busy && !draft.trim() && !attachments.length} onClick={busy ? stop : send} aria-label={busy ? "Stop response" : "Send message"} tabIndex={0}>
                        {busy ? <Square className="art:size-4"/> : (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up art:size-4.5" aria-hidden="true">
                          <path d="m5 12 7-7 7 7"/>
                          <path d="M12 19V5"/>
                        </svg>)}
                      </StudioButton>
                    </ArtemisMorphicTooltip>
                  </div>
                </div>
              </div>
            </div>
          </motion.div>
          <input id={fileId} ref={fileRef} type="file" multiple hidden onChange={event => { addFiles(Array.from(event.currentTarget.files ?? [])); event.currentTarget.value = ""; }}/>
        </div>
      </div>
    </ArtemisMorphicTooltipProvider>);
}

"use client";
// @zeus-internal
import { StudioButton } from "./button";
import { type MotionValue, animate, frame, motion, visualElementStore, useMotionValue, useReducedMotion } from "motion/react";
import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState, type AnimationEvent as ReactAnimationEvent, type CSSProperties, type KeyboardEvent as ReactKeyboardEvent, type MouseEvent as ReactMouseEvent, type PointerEvent as ReactPointerEvent, type ReactNode, } from "react";
